-- Generated from lib/seed-data.ts. Re-run with: npx tsx scripts/emit-seed-sql.ts
insert into books (
  id, owner_id, title, author, cover_url, synopsis, genre, format, rating, review, isbn, status, created_at
) values
  ('10000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001', 'The Hobbit', 'J.R.R. Tolkien', 'https://covers.openlibrary.org/b/isbn/9780547928227-L.jpg', 'A comfort-loving hobbit is talked into a journey and comes home with a better story than he left with. I keep it for the firelight chapters.', 'Fantasy', 'physical', 5, 'The book I lend first. It still feels like being walked to the door of a larger world and told I may come along.', '9780547928227', 'available', '2024-01-08T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000001', 'The Name of the Wind', 'Patrick Rothfuss', 'https://covers.openlibrary.org/b/isbn/9780756404741-L.jpg', 'A magician tells his own legend over a single night in an inn, and the telling is more careful than the myth.', 'Fantasy', 'physical', 5, 'I reread the frame story more than the fireworks. The silence in the inn is what I came for.', '9780756404741', 'available', '2024-01-20T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000001', 'A Wizard of Earthsea', 'Ursula K. Le Guin', 'https://covers.openlibrary.org/b/isbn/9780547773742-L.jpg', 'A proud student of magic releases his own shadow and has to cross the sea to meet it.', 'Fantasy', 'physical', 5, 'Short, severe, and kind. This copy is out at the moment. I miss it on the shelf.', '9780547773742', 'lent', '2024-02-02T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000004', '00000000-0000-4000-8000-000000000001', 'Piranesi', 'Susanna Clarke', 'https://covers.openlibrary.org/b/isbn/9781635575637-L.jpg', 'A man catalogs an endless house of statues and tides, until the house turns out to have a door he did not build.', 'Fantasy', 'epub', 5, 'I read this on a train and kept looking up as if the carriage had grown additional halls. The digital copy is the one I return to.', '9781635575637', 'available', '2024-02-18T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000000001', 'The Night Circus', 'Erin Morgenstern', 'https://covers.openlibrary.org/b/isbn/9780307744432-L.jpg', 'Two illusionists are bound into a contest staged inside a circus that opens only after dark.', 'Fantasy', 'physical', 4, 'More atmosphere than plot, which is why it lives in this room. I open it when I want the lamps lower.', '9780307744432', 'available', '2024-03-01T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000006', '00000000-0000-4000-8000-000000000001', 'The Lies of Locke Lamora', 'Scott Lynch', 'https://covers.openlibrary.org/b/isbn/9780553588941-L.jpg', 'A crew of confidence artists in a canal city attempts one elegant theft and finds the city less forgiving than the plan.', 'Fantasy', 'epub', 4.5, 'The dialogue is the plot. I keep the file for journeys and still wish the binding were cloth.', '9780553588941', 'available', '2024-03-14T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000007', '00000000-0000-4000-8000-000000000001', 'Pride and Prejudice', 'Jane Austen', 'https://covers.openlibrary.org/b/isbn/9780141439518-L.jpg', 'Elizabeth Bennet and Mr. Darcy misread each other in a drawing room until the misreading becomes the romance.', 'Classics', 'physical', 5, 'The sentences are so exact that I read some of them aloud to an empty chair. It never feels like a duty.', '9780141439518', 'available', '2024-03-28T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000008', '00000000-0000-4000-8000-000000000001', 'Jane Eyre', 'Charlotte Bronte', 'https://covers.openlibrary.org/b/isbn/9780141441146-L.jpg', 'A governess with a strict sense of herself takes a post in a house that is keeping a secret on the third floor.', 'Classics', 'physical', 5, 'I loved her stubbornness before I trusted the plot. The red room chapter still changes the temperature of the library.', '9780141441146', 'available', '2024-04-09T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000009', '00000000-0000-4000-8000-000000000001', 'Frankenstein', 'Mary Shelley', 'https://covers.openlibrary.org/b/isbn/9780141439471-L.jpg', 'A student builds a person and then refuses the responsibility that creation asked of him.', 'Classics', 'physical', 4.5, 'Slim enough to finish in an evening and large enough to ruin the evening in a useful way.', '9780141439471', 'available', '2024-04-22T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000010', '00000000-0000-4000-8000-000000000001', 'Crime and Punishment', 'Fyodor Dostoevsky', 'https://covers.openlibrary.org/b/isbn/9780143058144-L.jpg', 'A student tests a theory about extraordinary men, commits a murder, and spends the rest of the book unable to live inside the theory.', 'Classics', 'physical', 5, 'I read it too young and then again when I could hear the fever in the prose. The second time is the one I trust.', '9780143058144', 'available', '2024-05-06T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000011', '00000000-0000-4000-8000-000000000001', 'Great Expectations', 'Charles Dickens', 'https://covers.openlibrary.org/b/isbn/9780141439563-L.jpg', 'Pip is given money and a story about where it came from, and both turn out to be a kind of haunting.', 'Classics', 'epub', 4, 'I keep the file because the paperback fell apart. The marshes at the beginning are still the best weather in fiction.', '9780141439563', 'available', '2024-05-19T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000012', '00000000-0000-4000-8000-000000000001', 'The Odyssey', 'Homer', 'https://covers.openlibrary.org/b/isbn/9780140268867-L.jpg', 'After the war, a man tries to get home while his house tries not to forget him. The sea is the long way around.', 'Classics', 'physical', 4.5, 'I use the Fagles when I want the voice in the room. Some nights I only read the return.', '9780140268867', 'available', '2024-06-02T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000013', '00000000-0000-4000-8000-000000000001', 'The Design of Everyday Things', 'Don Norman', 'https://covers.openlibrary.org/b/isbn/9780465050659-L.jpg', 'A patient argument that confusion is usually a property of the object, not a failing of the person holding it.', 'Design', 'physical', 5, 'I leave this where I can reach it when a project starts blaming the user. The door chapter has saved me more than once.', '9780465050659', 'available', '2024-06-16T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000014', '00000000-0000-4000-8000-000000000001', 'Grid Systems in Graphic Design', 'Josef Muller-Brockmann', 'https://covers.openlibrary.org/b/isbn/9783721201451-L.jpg', 'A Swiss manual for organizing a page so that type, image, and silence share one structure.', 'Design', 'physical', 5, 'I do not follow it strictly. I like having it open nearby when a layout is getting loud.', '9783721201451', 'available', '2024-07-01T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000015', '00000000-0000-4000-8000-000000000001', 'Thinking with Type', 'Ellen Lupton', 'https://covers.openlibrary.org/b/isbn/9781568989693-L.jpg', 'A field guide to letters, spacing, and the small decisions that make a page feel considered.', 'Design', 'physical', 4.5, 'The one I actually hand to people. Clear without being cold, which is rare for a book about rules.', '9781568989693', 'available', '2024-07-18T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000016', '00000000-0000-4000-8000-000000000001', 'Interaction of Color', 'Josef Albers', 'https://covers.openlibrary.org/b/isbn/9780300179354-L.jpg', 'Color is not a chip you pick. It changes according to whatever you set beside it.', 'Design', 'epub', 4.5, 'The plates want paper, and I know that. I still reread the exercises when a palette starts to lie to me.', '9780300179354', 'available', '2024-08-02T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000017', '00000000-0000-4000-8000-000000000001', 'The Elements of Typographic Style', 'Robert Bringhurst', 'https://covers.openlibrary.org/b/isbn/9780881792126-L.jpg', 'A craftsman''s book on rhythm, proportion, and the manners of type on a page.', 'Design', 'physical', 5, 'I read a few pages at a time, the way it seems to expect. It made me slower in a way I wanted.', '9780881792126', 'available', '2024-08-20T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000018', '00000000-0000-4000-8000-000000000001', 'Design as Art', 'Bruno Munari', 'https://covers.openlibrary.org/b/isbn/9780141035819-L.jpg', 'Short essays on orange peel, lamps, and the idea that design is a form of courtesy.', 'Design', 'physical', 4, 'Light in the hand and serious underneath. Good company on the side table.', '9780141035819', 'available', '2024-09-04T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000019', '00000000-0000-4000-8000-000000000001', 'Meditations', 'Marcus Aurelius', 'https://covers.openlibrary.org/b/isbn/9780140449334-L.jpg', 'Private notes from a Roman emperor to himself about how to meet the day without making it worse.', 'Self-Help', 'physical', 5, 'Not a system. A voice I trust when the week has been noisy. I keep the bookmark near the morning pages.', '9780140449334', 'available', '2024-09-18T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000020', '00000000-0000-4000-8000-000000000001', 'Man''s Search for Meaning', 'Viktor Frankl', 'https://covers.openlibrary.org/b/isbn/9780807014295-L.jpg', 'A psychiatrist writes about the camps and the idea that a person can choose the stance they take toward suffering.', 'Self-Help', 'physical', 5, 'I don''t lend this lightly. When I do, I want it back with the pencil marks still in it.', '9780807014295', 'available', '2024-10-02T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000021', '00000000-0000-4000-8000-000000000001', 'Atomic Habits', 'James Clear', 'https://covers.openlibrary.org/b/isbn/9780735211292-L.jpg', 'A practical book about making small changes easier to repeat than to negotiate with.', 'Self-Help', 'physical', 4, 'Less literature than the rest of this shelf, and useful on purpose. I stole the habit-stacking page for my own notebook.', '9780735211292', 'available', '2024-10-16T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000022', '00000000-0000-4000-8000-000000000001', 'Deep Work', 'Cal Newport', 'https://covers.openlibrary.org/b/isbn/9781455586691-L.jpg', 'An argument for protecting long, undistracted stretches of attention, and a set of ways to defend them.', 'Self-Help', 'epub', 4, 'I argue with the austerity and still close the laptop when it tells me to. The file lives on the reading tablet.', '9781455586691', 'available', '2024-11-01T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000023', '00000000-0000-4000-8000-000000000001', 'The War of Art', 'Steven Pressfield', 'https://covers.openlibrary.org/b/isbn/9781936891023-L.jpg', 'A blunt little book about the resistance that shows up the moment a person tries to do the work they mean to do.', 'Self-Help', 'physical', 4.5, 'I reread it in an afternoon when I am stalling. It does not comfort me. That is the point.', '9781936891023', 'available', '2024-11-15T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000024', '00000000-0000-4000-8000-000000000001', 'Four Thousand Weeks', 'Oliver Burkeman', 'https://covers.openlibrary.org/b/isbn/9780374159122-L.jpg', 'A refusal of the fantasy that a well-run life will eventually contain everything. Time is short, so choose.', 'Self-Help', 'epub', 5, 'The self-help book I trust because it declines to optimize me. I underlined half of it and felt lighter.', '9780374159122', 'available', '2024-12-02T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000025', '00000000-0000-4000-8000-000000000001', 'SPQR', 'Mary Beard', 'https://covers.openlibrary.org/b/isbn/9781631492228-L.jpg', 'A history of Rome that prefers citizens, rumors, and evidence over the marble version of the empire.', 'History', 'physical', 5, 'Beard is good company for a long evening. I come away less impressed by emperors and more interested in the crowd.', '9781631492228', 'available', '2025-01-10T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000026', '00000000-0000-4000-8000-000000000001', 'The Silk Roads', 'Peter Frankopan', 'https://covers.openlibrary.org/b/isbn/9781101912379-L.jpg', 'A retelling of world history that starts from the routes between Asia and the Mediterranean instead of from the north Atlantic.', 'History', 'physical', 4.5, 'Out with a friend who is traveling. I want the maps back as much as the prose.', '9781101912379', 'lent', '2025-01-24T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000027', '00000000-0000-4000-8000-000000000001', 'The Guns of August', 'Barbara Tuchman', 'https://covers.openlibrary.org/b/isbn/9780345476098-L.jpg', 'The first month of the First World War, told so that the catastrophe feels like a sequence of choices.', 'History', 'physical', 5, 'The narrative pull is almost unfair. I sat down to sample a chapter and left the lamp on until the end.', '9780345476098', 'available', '2025-02-08T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000028', '00000000-0000-4000-8000-000000000001', 'A Distant Mirror', 'Barbara Tuchman', 'https://covers.openlibrary.org/b/isbn/9780345349576-L.jpg', 'The fourteenth century, seen through one noble house, as plague, war, and spectacle rearrange Europe.', 'History', 'physical', 4.5, 'Heavier than Guns of August and just as alive. I read it in winter and the room felt correctly old.', '9780345349576', 'available', '2025-02-22T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000029', '00000000-0000-4000-8000-000000000001', 'Sapiens', 'Yuval Noah Harari', 'https://covers.openlibrary.org/b/isbn/9780062316097-L.jpg', 'A brisk history of our species that trades caution for a very wide lens.', 'History', 'epub', 3.5, 'I enjoyed the sweep and distrusted the certainty. Worth the argument it started with a friend. Not a book I treat as settled.', '9780062316097', 'available', '2025-03-09T15:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000030', '00000000-0000-4000-8000-000000000001', 'The Warmth of Other Suns', 'Isabel Wilkerson', 'https://covers.openlibrary.org/b/isbn/9780679763888-L.jpg', 'The Great Migration told through three lives, with the scale of an epic and the patience of a reported portrait.', 'History', 'physical', 5, 'The book on this wall I most want someone to sit down with. I still remember where I was when I finished it.', '9780679763888', 'available', '2025-03-28T15:00:00.000Z')
on conflict (id) do nothing;
